    if opts['list'] and opts['listall']: return die('--list and --list-all cannot be used together',1)
    taskfile=find_file(directory,opts['taskfile'])
    if taskfile is None:
        attempted=opts['taskfile'] or ''
        if opts['taskfile']: return die(f'No Taskfile found at "{attempted}" Run `task --init` to create a new Taskfile.',100)
        return die(f'No Taskfile found at "" (or any of the parent directories). Run `task --init` to create a new Taskfile.',100)
